// 只掃「上次掃過之後」的新執行，掃過的記在 workflow static data 裡，不會重複推播。
const s = $getWorkflowStaticData('global');
const all = ($input.first().json.data || []).filter(e => e.stoppedAt);
const maxId = all.reduce((m, e) => Math.max(m, Number(e.id || 0)), 0);
// 第一次跑：只把基準線設在「現在」，不回頭翻歷史（歷史問題已經人工處理過了）
if (s.lastExecId === undefined) { s.lastExecId = maxId; return []; }
const last = Number(s.lastExecId || 0);
const rows = all
  .filter(e => Number(e.id) > last)
  .sort((a, b) => Number(a.id) - Number(b.id))
  .slice(0, 15);              // 一次最多 15 筆，避免打爆自己
return rows.length ? rows.map(e => ({ json: { id: e.id } })) : [];

// 走訪每一筆執行的所有節點輸出，找出「有錯但被容錯吞掉」的那些。
// 判準：節點輸出的 json 帶著 error 物件。離線對 60 筆執行試掃過，零誤報。
const IGNORE = [];   // 未來若有節點天生就會回 error（且屬預期），把節點名加進來
const found = [];
let maxId = 0;
for (const item of $input.all()) {
  const d = item.json || {};
  maxId = Math.max(maxId, Number(d.id || 0));
  const wfName = (d.workflowData && d.workflowData.name) || d.workflowId || '未知流程';
  const runData = ((d.data || {}).resultData || {}).runData || {};
  for (const [node, runs] of Object.entries(runData)) {
    if (IGNORE.includes(node)) continue;
    for (const run of runs) {
      for (const branch of ((run.data || {}).main || [])) {
        for (const it of (branch || [])) {
          const j = (it || {}).json;
          if (j && typeof j === 'object' && j.error && typeof j.error === 'object') {
            const msg = String(j.error.message || JSON.stringify(j.error)).slice(0, 160);
            found.push({ execId: d.id, wfName, node, msg });
          }
        }
      }
    }
  }
}
const s = $getWorkflowStaticData('global');
if (maxId) s.lastExecId = maxId;
// 同一個節點同一種錯只報一次
const seen = new Set();
const uniq = found.filter(f => {
  const k = f.wfName + '|' + f.node + '|' + f.msg.slice(0, 60);
  if (seen.has(k)) return false;
  seen.add(k); return true;
});
return uniq.length ? [{ json: { count: uniq.length, items: uniq } }] : [];

const d = $input.first().json;
const lines = d.items.map(f =>
  `・${f.wfName} → ${f.node}
　執行 #${f.execId}
　${f.msg}`).join('

');
const text = `🔕 有動作失敗了但流程沒報錯（${d.count} 筆）

`
  + `這些節點設了容錯，失敗會被吞掉、執行狀態還是「成功」，所以不會觸發一般的錯誤告警。

`
  + lines + `

`
  + `⚠️ 廣告線出現這種，先確認貼文／Notion／KEIS 三邊有沒有對上。`;
return [{ json: { text } }];
